design.css:
/* Spotlight — the Anikoto look (docs/theme-references/anikoto.md): navy #0b1622, one sky-blue accent, Nunito. */

/* Header: a 60 px #142030 bar row with no rule under it, the 581 px search field after the brand, 13.2 px links. */
:scope { --theme-top-row: 60px; }
[data-slot="nav.top"] { background: #142030 !important; border-bottom-color: transparent !important; }
[data-slot="nav.top"] > [data-part="nav.item"] { order: 3; gap: 6px; padding: 0 10px; color: #a0b1c5; font-size: 13.2px; font-weight: 600; }
[data-slot="nav.top"] > [data-part="nav.item"]:hover { background: transparent; color: #26a3d6; }
[data-slot="nav.top"] > [data-part="nav.item"][data-active] { color: #26a3d6; }
[data-slot="nav.top"] [data-part="nav.item.icon"] svg { width: 16px; height: 16px; }
[data-slot="nav.top"] > div:has([data-part="search.field"]) { order: 2; flex: 0 1 581px; margin: 0 auto 0 38px; padding: 0; }
[data-slot="nav.top"] > div:has([data-part="search.field"]) > form { width: 100%; max-width: none; }
[data-slot="nav.top"] > button:not([data-part]), [data-slot="nav.top"] > a:not([data-part]), [data-slot="nav.top"] > [data-part="nav.action"] { order: 4; }
[data-slot="nav.top"] [data-part="search.field"] { height: 36px; border: 0; border-radius: 6px; background: #101925; color: #a0b1c5; font-size: 13.2px; font-weight: 500; }
/* The account control is the blue "Sign in" button at the end of the bar (label, then the icon). */
[data-slot="nav.top"] > [data-part="nav.action"][data-action="account"] { display: flex !important; flex-direction: row-reverse; gap: 6px; width: auto !important; height: 35px !important; margin-left: 6px; padding: 0 20px !important; border: 1px solid #26a3d6; border-radius: 6px !important; background: #26a3d6 !important; color: #fff !important; font-size: 15px; }
[data-slot="nav.top"] > [data-part="nav.action"][data-action="account"] > span:not([data-part]) { width: auto; }
[data-slot="nav.top"] > [data-part="nav.action"][data-action="account"] svg { width: 18px; height: 18px; }
[data-slot="nav.top"] [data-part="nav.action"][data-action="account"] [data-part="nav.action.label"] { position: static; width: auto; height: auto; margin: 0; overflow: visible; clip: auto; white-space: nowrap; font-size: 15px; font-weight: 400; line-height: 35px; }
[data-slot="nav.top"] > [data-part="nav.action"]:not([data-action="account"]) { color: #a0b1c5; }

/* Hero: full width, 510 px under the bar, the art fading into the page from the left and the bottom. */
[data-slot="home.hero"] { width: auto !important; height: 510px !important; margin: 0 0 30px !important; border-radius: 0 !important; background: #0b1622; }
[data-part="spot.hero"] { height: 100%; }
[data-part="spot.art"] img { object-position: 70% 50%; }
[data-part="spot.hero"]::after {
  content: "";
  position: absolute;
  inset: 0;
  z-index: 1;
  background-image: linear-gradient(90deg, #0b1622 0%, rgba(11, 22, 34, 0.95) 26%, rgba(11, 22, 34, 0.55) 46%, rgba(11, 22, 34, 0.12) 68%, rgba(11, 22, 34, 0) 82%), linear-gradient(0deg, #0b1622 0%, rgba(11, 22, 34, 0) 45%, rgba(11, 22, 34, 0.4) 100%);
  pointer-events: none;
}
[data-part="spot.hero"] > :not(:first-child) { z-index: 2; }
[data-part="spot.info"] { width: 656px; padding: 0 40px 50px !important; color: #a0b1c5; }
[data-part="spot.info"] > [data-part="spot.sub"] { margin-bottom: 8px; color: #26a3d6; line-height: 21.6px; }
[data-part="spot.sub-label"] { margin-left: 4px; }
[data-part="spot.title"] { margin-bottom: 8px; line-height: 1.15 !important; }
[data-part="spot.detail"] { margin-bottom: 12px; color: #a0b1c5; line-height: 19.8px; }
[data-part="spot.detail"] > * { display: inline-flex; align-items: center; }
[data-part="spot.detail"] > *::before { content: ""; flex: none; width: 11.88px; height: 11.88px; margin-right: 5px; opacity: 0.6; background-color: currentColor; -webkit-mask: center / contain no-repeat; mask: center / contain no-repeat; }
[data-part="spot.it-format"]::before { -webkit-mask-image: url(data:image/svg+xml;base64,PHN2ZyB4bWxucz0iaHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmciIHZpZXdCb3g9IjAgMCAxNiAxNiI+PHBhdGggZmlsbC1ydWxlPSJldmVub2RkIiBkPSJNOCAwYTggOCAwIDEgMCAwIDE2QTggOCAwIDAgMCA4IDB6TTYuMiA0LjZ2Ni44TDExLjYgOHoiLz48L3N2Zz4=); mask-image: url(data:image/svg+xml;base64,PHN2ZyB4bWxucz0iaHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmciIHZpZXdCb3g9IjAgMCAxNiAxNiI+PHBhdGggZmlsbC1ydWxlPSJldmVub2RkIiBkPSJNOCAwYTggOCAwIDEgMCAwIDE2QTggOCAwIDAgMCA4IDB6TTYuMiA0LjZ2Ni44TDExLjYgOHoiLz48L3N2Zz4=); }
[data-part="spot.it-date"]::before { -webkit-mask-image: url(data:image/svg+xml;base64,); mask-image: url(data:image/svg+xml;base64,); }
[data-part="spot.it-score"]::before { opacity: 1 !important; background-color: #e0a458 !important; -webkit-mask-image: url(data:image/svg+xml;base64,PHN2ZyB4bWxucz0iaHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmciIHZpZXdCb3g9IjAgMCAxNiAxNiI+PHBhdGggZD0iTTggLjRsMi4zNSA0Ljg1IDUuMy43NS0zLjg1IDMuNy45MiA1LjNMOCAxMi41IDMuMjggMTVsLjkyLTUuM0wuMzUgNmw1LjMtLjc1eiIvPjwvc3ZnPg==); mask-image: url(data:image/svg+xml;base64,PHN2ZyB4bWxucz0iaHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmciIHZpZXdCb3g9IjAgMCAxNiAxNiI+PHBhdGggZD0iTTggLjRsMi4zNSA0Ljg1IDUuMy43NS0zLjg1IDMuNy45MiA1LjNMOCAxMi41IDMuMjggMTVsLjkyLTUuM0wuMzUgNmw1LjMtLjc1eiIvPjwvc3ZnPg==); }
[data-part="spot.it-eps"]::before { -webkit-mask-image: url(data:image/svg+xml;base64,PHN2ZyB4bWxucz0iaHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmciIHZpZXdCb3g9IjAgMCAxNiAxNiI+PHBhdGggZmlsbC1ydWxlPSJldmVub2RkIiBkPSJNMCAxLjVoMTZ2MTNIMHpNMS41IDN2MmgyVjN6bTAgNHYyaDJWN3ptMCA0djJoMnYtMnptMTEtOHYyaDJWM3ptMCA0djJoMlY3em0wIDR2Mmgydi0yek01IDN2MTBoNlYzeiIvPjwvc3ZnPg==); mask-image: url(data:image/svg+xml;base64,PHN2ZyB4bWxucz0iaHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmciIHZpZXdCb3g9IjAgMCAxNiAxNiI+PHBhdGggZmlsbC1ydWxlPSJldmVub2RkIiBkPSJNMCAxLjVoMTZ2MTNIMHpNMS41IDN2MmgyVjN6bTAgNHYyaDJWN3ptMCA0djJoMnYtMnptMTEtOHYyaDJWM3ptMCA0djJoMlY3em0wIDR2Mmgydi0yek01IDN2MTBoNlYzeiIvPjwvc3ZnPg==); }
[data-part="spot.synopsis"] { margin-bottom: 18px; color: #a0b1c5; font-weight: 300 !important; line-height: 22.08px; }
[data-part="spot.play"] { min-height: 0 !important; height: 37.7px; padding: 0 21.6px !important; gap: 5px !important; border: 1px solid #26a3d6; line-height: 22.5px; }
[data-part="spot.play"] svg { width: 12px; height: 12px; fill: currentColor; }
[data-part="spot.nav"] { right: 30px !important; bottom: 50px !important; left: auto !important; padding: 0 !important; }
[data-part="spot.prev"], [data-part="spot.next"] { display: grid !important; place-items: center; width: 40px; min-width: 0 !important; height: 40px; min-height: 0 !important; padding: 0 !important; border: 0 !important; border-radius: 5px !important; background: #142030 !important; color: #a0b1c5 !important; opacity: 0.75; box-shadow: none !important; }
[data-part="spot.prev"]:hover, [data-part="spot.next"]:hover { opacity: 1; }
/* The site pages the hero only with these two buttons; izumi's hover edge arrows would sit on top of them. */
[data-slot="home.hero"] [data-part="hero.edge"] { display: none !important; }

/* Columns: 10 px page gutters, a 336 px aside 20 px from the main column. */
[data-slot="home.main"] [data-block] { padding-left: 10px !important; padding-right: 10px !important; margin-bottom: 40px !important; }
[data-slot="home.aside"] [data-block] { padding-right: 10px !important; }
[data-slot="home.main"] [data-part="row.header"] { padding-left: 10px !important; padding-right: 10px !important; margin-bottom: 15px; }
[data-slot="home.main"] [data-part="row.track"] { padding-left: 10px !important; padding-right: 10px !important; }
[data-slot="home.main"] [data-slot="row"] { margin-bottom: 40px; }

/* Section headings: 24 px / 600 #ddd on a 36 px line; "View more" in #515f75. */
[data-part="row.title"], [data-part="block.title"] { font-size: 24px !important; font-weight: 600 !important; line-height: 36px !important; color: #ddd; }
[data-part="row.more"] { color: #515f75; font-size: 13.2px; font-weight: 400; }
[data-part="row.more"]:hover { color: #26a3d6; }

/* Latest Episode: the text tabs and the page arrows share the heading's line. */
[data-slot="block.tabbed-grid"] { display: grid; grid-template-columns: minmax(0, 1fr) auto auto; align-items: center; }
[data-slot="block.tabbed-grid"] > [data-part="block.title"] { grid-column: 1; grid-row: 1; margin: 0 0 15px; }
[data-slot="block.tabbed-grid"] > div[data-nav-row]:not([data-nav-row-items]) { grid-column: 2; grid-row: 1; margin-bottom: 15px; }
[data-slot="block.tabbed-grid"] > [data-part="pagination"] { grid-column: 3; grid-row: 1; margin: 0 0 15px 8px; gap: 0; }
[data-slot="block.tabbed-grid"] > div[data-nav-row-items] { grid-column: 1 / -1; grid-row: 2; column-gap: 20px !important; row-gap: 20px !important; }
[data-slot="block.tabbed-grid"] [data-part="tabs"] { margin: 0; padding: 0; gap: 8px; border: 0; background: transparent; }
[data-slot="block.tabbed-grid"] [data-part="tab"] { padding: 0 3px; border: 0; background: transparent; color: #515f75; font-size: 14.4px; font-weight: 400; line-height: 21.6px; }
[data-slot="block.tabbed-grid"] [data-part="tab"]:hover, [data-slot="block.tabbed-grid"] [data-part="tab"][data-active] { color: #26a3d6; }
[data-slot="block.tabbed-grid"] [data-part="tab"] > span { display: none; }
[data-slot="block.tabbed-grid"] [data-part="page-step"] { display: grid; place-items: center; width: 19px; height: 26px; padding: 0; border-radius: 0; background: transparent !important; color: #a0b1c5; }
[data-slot="block.tabbed-grid"] [data-part="page-step"]:disabled { opacity: 0.4; }
[data-slot="block.tabbed-grid"] [data-part="page-step"] svg { width: 14px; height: 14px; }

/* Poster cards: 158 x 221 posters with 5 px corners, a 24 px navy meta bar over their foot (a skewed blue
   sub count with a CC mark, the total on slate, the format at the end), the title in 14.4 px slate-blue. */
[data-part="spot.poster"] { aspect-ratio: 158 / 221.4; border-radius: 5px; overflow: hidden; }
[data-part="spot.poster"] img { border-radius: 0 0 6px 6px; }
[data-part="spot.meta"] { width: 100%; height: 24px; padding: 0 5px; background: #19273b; color: #a0b1c5; line-height: 24px; }
[data-part="spot.meta"] > [data-part="spot.sub"], [data-part="spot.rk-meta"] > [data-part="spot.sub"], [data-part="spot.total"] { position: relative; isolation: isolate; height: 15.47px; margin-right: 4px; padding: 0 3px; color: rgba(255, 255, 255, 0.8); line-height: 15.48px; }
[data-part="spot.meta"] > [data-part="spot.sub"], [data-part="spot.rk-meta"] > [data-part="spot.sub"] { padding-left: 4px; }
[data-part="spot.meta"] > [data-part="spot.sub"]::after, [data-part="spot.rk-meta"] > [data-part="spot.sub"]::after, [data-part="spot.total"]::after { content: ""; position: absolute; inset: 0; z-index: -1; border-radius: 1.5px; background: #0084b9; transform: skewX(-15deg); }
[data-part="spot.total"] { color: rgba(255, 255, 255, 0.6); }
[data-part="spot.total"]::after { background: #2a3f5c; }
[data-part="spot.meta"] > [data-part="spot.sub"]::before, [data-part="spot.rk-meta"] > [data-part="spot.sub"]::before { content: ""; width: 12.375px; height: 12.375px; margin-right: 3px; opacity: 0.7; background-color: currentColor; -webkit-mask: url(data:image/svg+xml;base64,) center / contain no-repeat; mask: url(data:image/svg+xml;base64,) center / contain no-repeat; }
[data-part="spot.format"] { margin-left: auto; color: #a0b1c5; }
[data-part="spot.name"] { min-height: 36px; margin: 10.8px 0 9px; color: #a0b1c5; line-height: 18px; }
[data-part="card"]:hover [data-part="spot.name"] { color: #26a3d6; }

/* Top anime aside: the title and a segmented #142030 range switch on one line; a lead card for #1, then
   62 px rows with small coloured ranks, 36 x 50 posters and 13.8 px titles (the API 5 ranked card template). */
[data-slot="block.ranked-list"] { display: grid; grid-template-columns: minmax(0, 1fr) auto; align-items: center; column-gap: 8px; }
[data-slot="block.ranked-list"] > [data-part="block.title"] { margin: 0; padding-left: 5px; }
[data-slot="block.ranked-list"] > ol { grid-column: 1 / -1; margin-top: 15px; }
[data-slot="block.ranked-list"] > ol > li { margin: 0 0 2px !important; }
[data-slot="block.ranked-list"] > ol > li:first-child { margin-bottom: 8px !important; }
[data-slot="block.ranked-list"] [data-part="tabs"] { margin: 0; gap: 2px; padding: 3px; border-radius: 5px; background: #142030; }
[data-slot="block.ranked-list"] [data-part="tab"] { height: 22px; padding: 2px 8px; border-radius: 3px; background: transparent; color: #8097b2; font-size: 12px; font-weight: 600; line-height: 18px; box-shadow: none; }
[data-slot="block.ranked-list"] [data-part="tab"][data-active] { background: #26a3d6; color: #eee; }
[data-slot="block.ranked-list"] [data-part="block.item"] { border-radius: 5px; }
[data-part="spot.rk"] { position: relative; isolation: isolate; padding: 6px; border-radius: 5px; overflow: hidden; }
[data-part="spot.rk-n"] { flex: none; width: 22px; color: #515f75; line-height: 22.5px; text-align: center; }
[data-slot="block.ranked-list"] li:nth-child(2) [data-part="spot.rk-n"] { color: #bd4c60; }
[data-slot="block.ranked-list"] li:nth-child(3) [data-part="spot.rk-n"] { color: #ab8445; }
[data-part="spot.rk-poster"] { flex: none; width: 36px !important; height: 50px; border-radius: 3px; overflow: hidden; }
[data-part="spot.rk-poster"] img { width: 100%; height: 100%; object-fit: cover; }
[data-part="spot.rk-tx"] { flex: 1 1 auto; min-width: 0; }
[data-part="spot.rk-name"] { margin-bottom: 2px; color: #a0b1c5; line-height: 17.94px !important; }
[data-part="spot.rk-meta"] { color: #515f75; line-height: 16.2px; }
[data-part="spot.rk-format"] { margin-left: 6px; }
[data-slot="block.ranked-list"] [data-part="block.item"]:hover [data-part="spot.rk-name"] { color: #26a3d6; }
[data-slot="block.ranked-list"] li:first-child [data-part="spot.rk"] { align-items: flex-end !important; min-height: 150px; gap: 12px !important; padding: 12px; background: #142030; }
[data-slot="block.ranked-list"] li:first-child [data-part="spot.rk"]::after { content: ""; position: absolute; inset: 0; z-index: -1; background-image: linear-gradient(0deg, #0b1622 0px, rgba(11, 22, 34, 0.35) 60%, rgba(11, 22, 34, 0.1) 100%); pointer-events: none; }
[data-part="spot.rk-bg"] { z-index: -1; inset: -20px !important; width: auto !important; height: auto !important; filter: blur(14px) brightness(0.55); }
[data-part="spot.rk-bg"] img { width: 100%; height: 100%; object-fit: cover; }
[data-slot="block.ranked-list"] li:first-child [data-part="spot.rk-n"] { display: none; }
[data-slot="block.ranked-list"] li:first-child [data-part="spot.rk-poster"] { width: 76px !important; height: 106px; border-radius: 4px; }
[data-part="spot.rk-label"] { margin-bottom: 2px; color: #26a3d6; line-height: 18px; text-transform: uppercase; }
[data-slot="block.ranked-list"] li:first-child [data-part="spot.rk-name"] { margin-bottom: 4px; color: #fff; font-size: 17.4px !important; font-weight: 700 !important; line-height: 22.62px !important; }
[data-slot="block.ranked-list"] li:first-child [data-part="spot.rk-meta"] { padding-bottom: 2px; color: #a0b1c5; line-height: 17.1px; }
[data-slot="block.ranked-list"] li:first-child [data-part="spot.rk-meta"] :is(span, div) { font-size: 11.4px !important; }
[data-slot="block.ranked-list"] li:first-child [data-part="spot.rk-format"] { font-weight: 300 !important; }

/* Series page (desktop): the site's watch layout. A 1100 px main column holds the artwork in the
   player's 597 px box, the episode box and the info block; a 300 px aside holds Related, then
   Recommended from the info block down. Cast follows the info block in the main column. */
[data-slot="detail"][data-variant="desktop"][data-layout="stack"] { display: grid; grid-template-columns: minmax(0, 1fr) 300px; grid-template-rows: auto auto auto auto 1fr; column-gap: 20px; align-items: start; padding: 10px 10px 64px; }
[data-slot="detail"][data-variant="desktop"][data-layout="stack"] > div:has(> [data-slot="detail.banner"]) { grid-column: 1; grid-row: 1; }
[data-slot="detail"][data-variant="desktop"][data-layout="stack"] > [data-part="detail.content"] { display: contents; }
[data-slot="detail"][data-variant="desktop"][data-layout="stack"] > [data-part="detail.content"] > div:has([data-part="detail.title"]) { grid-column: 1; grid-row: 3; align-items: flex-start; gap: 15px; margin: 30px 0 0; }
[data-slot="detail"][data-variant="desktop"] [data-slot="detail.section"] { margin-top: 0; }
[data-slot="detail"][data-variant="desktop"] [data-slot="detail.section"][data-section="episodes"] { grid-column: 1; grid-row: 2; margin-top: 10px; border-radius: 5px; background: #050a0f; }
[data-slot="detail"][data-variant="desktop"] [data-slot="detail.section"][data-section="relations"] { grid-column: 2; grid-row: 1 / 4; }
[data-slot="detail"][data-variant="desktop"] [data-slot="detail.section"][data-section="recommended"] { grid-column: 2; grid-row: 4 / 6; margin-top: 20px; }
[data-slot="detail"][data-variant="desktop"] [data-slot="detail.section"][data-section="characters"] { grid-column: 1; grid-row: 4; margin-top: 40px; }
[data-slot="detail"][data-variant="desktop"] [data-part="detail.section-title"] { margin: 0 0 15px; color: #ddd; font-size: 24px; font-weight: 600; line-height: 36px; }
[data-slot="detail"][data-variant="desktop"] [data-section="episodes"] > [data-part="detail.section-title"] { display: none; }

/* The artwork in the player box: 597 px, square corners, no scrim. */
[data-slot="detail"][data-variant="desktop"] [data-slot="detail.banner"] { height: 597px !important; margin: 0 !important; overflow: hidden; background: #000; }
[data-slot="detail"][data-variant="desktop"] [data-slot="detail.banner"] > div:first-child { left: 0 !important; width: 100% !important; height: 100% !important; }
[data-slot="detail"][data-variant="desktop"] [data-slot="detail.banner"] [data-part="hero.scrim"] { display: none; }

/* Episode box: #050a0f, a 45 px head of small #142030 controls, then 40 px rows (number, title),
   striped #0d141e / #111b29; the episode Play opens is the blue row with a play mark. */
[data-slot="detail"][data-variant="desktop"] [data-slot="episodes.toolbar"] { gap: 5px; margin: 0; padding: 10px; }
[data-slot="detail"][data-variant="desktop"] [data-slot="episodes.toolbar"] button, [data-slot="detail"][data-variant="desktop"] [data-slot="episodes.toolbar"] input { height: 23.75px !important; min-height: 0 !important; padding: 3px 9.6px !important; border: 1px solid #142030 !important; border-radius: 2.4px !important; background: #142030 !important; color: #8097b2 !important; font-size: 10.5px !important; font-weight: 400 !important; line-height: 15.75px !important; }
[data-slot="detail"][data-variant="desktop"] [data-slot="episodes.toolbar"] input { width: 152px !important; border-color: #20334d !important; background: #172537 !important; color: #a0b1c5 !important; }
[data-slot="detail"][data-variant="desktop"] [data-slot="episodes.toolbar"] svg { width: 10px; height: 10px; }
[data-slot="detail"][data-variant="desktop"] [data-part="episodes.search"] { flex: 0 0 auto !important; width: auto !important; }
[data-slot="detail"][data-variant="desktop"] [data-part="episodes.search"] > svg { display: none; }
[data-slot="detail"] [data-part="episodes.grid"] { gap: 0 !important; }
[data-slot="detail"][data-variant="desktop"] [data-part="episodes.grid"] { padding: 0 10px 10px !important; }
[data-slot="detail"] [data-part="episodes.grid"] [data-part="episode"] { height: 40px; min-height: 0; padding: 0; border: 1px solid #111b29; border-radius: 0; background: #0d141e; color: #8097b2; box-shadow: none; transform: none !important; }
[data-slot="detail"] [data-part="episodes.grid"] > :nth-child(even) [data-part="episode"] { background: #111b29; }
[data-slot="detail"] [data-part="episodes.grid"] [data-part="episode"]:hover { color: #26a3d6; }
[data-slot="detail"] [data-part="episodes.grid"] [data-part="episode"][data-next] { border-color: #26a3d6; background: #26a3d6; color: #eee; }
[data-part="spot.ep"] { height: 38px; padding-right: 38px; }
[data-part="spot.ep-no"] { flex: none; width: 38px; font-weight: 700 !important; text-align: center; }
[data-part="spot.ep-name"] { min-width: 0; flex: 1; }
